def min_plus_abs_max(a: int, b: int) -> int:
    m = a if a < b else b
    x = a if a > b else b
    return m + abs(x)

def max_minus_abs_min(a: int, b: int) -> int:
    m = a if a < b else b
    x = a if a > b else b
    return x - abs(m)

def nearest_to_zero(a: int, b: int) -> int:
    if abs(a) < abs(b):
        return a
    if abs(b) < abs(a):
        return b
    return a if a < b else b

def farthest_from_zero(a: int, b: int) -> int:
    if abs(a) > abs(b):
        return a
    if abs(b) > abs(a):
        return b
    return a if a > b else b

def sum_squared(a: int, b: int) -> int:
    s = a + b
    return s * s

def difference_squared(a: int, b: int) -> int:
    d = a - b
    return d * d

def sum_of_first_and_last_digits(a: int, b: int) -> int:
    sa = str(abs(a))
    sb = str(abs(b))
    return int(sa[0]) + int(sa[-1]) + int(sb[0]) + int(sb[-1])
